#include "openslope/player.hpp"
#include <nlohmann/json.hpp>
#include <chrono>
#include <fstream>
#include <iostream>
#include <stdexcept>

namespace {
using namespace openslope;using Json=nlohmann::json;unsigned checks=0;
void require(bool value,const char* message){++checks;if(!value)throw std::runtime_error(message);}
void near(double a,double b,double epsilon,const char* message){require(std::abs(a-b)<=epsilon,message);}
template<class F> void rejects(F operation,const char* message){bool rejected=false;try{operation();}catch(const std::exception&){rejected=true;}require(rejected,message);}
Patch floor(int surface=1){Patch p;p.surface=surface;p.lightmap=-1;for(unsigned u=0;u<4;++u)for(unsigned v=0;v<4;++v)p.points[u*4+v]={-1000+2000.*u/3,0,1000-2000.*v/3};return p;}
void crash_landing(Player& player,bool switched=false){player.warp({100,.1,0},switched?Vec3{0,0,1}:Vec3{0,0,-1},{0,-12,-12},{0,-1,0});player.tick({});require(player.rider().crashes==1&&player.rider().crash_cause==CrashCause::Landing&&player.rider().motion==Motion::Wipeout&&player.rider().control==Control::Wipeout,"Inverted landing enters one crash with the specified state pair");}
void clips(){
    auto clip=PoseAnimation::get_up({});clip.play();require(clip.pose().crouch==1&&clip.pose().height>.3&&clip.pose().standing==0,"Get-up starts in a crouched, raised pose");clip.tick(.25);near(clip.pose().standing,.2,1e-12,"Pose keys drive orientation progress");const auto pause=clip.pose();clip.tick(0);near(clip.pose().height,pause.height,0,"Zero animation time preserves the pose");require(!clip.take(PoseEvent::GetUpFinished),"No early get-up event");clip.tick(.95);require(!clip.playing()&&clip.take(PoseEvent::GetUpFinished),"Final standing key emits the animation completion event");require(!clip.take(PoseEvent::GetUpFinished),"Completion event is consumed once");near(clip.pose().height,0,0,"Completed get-up seats the board");
    PoseAnimation held({{0,0,1,.3},{.1,1,0,0}});held.play();for(unsigned i=0;i<600;++i)held.tick(1./60);require(!held.playing()&&!held.take(PoseEvent::GetUpFinished),"Track end without a marker cannot fabricate a completion event");clip.play();clip.stop();require(!clip.playing()&&!clip.take(PoseEvent::GetUpFinished),"Warp/reset stops and clears clip events");
    rejects([]{PoseAnimation({{0,0,1,0},{0,1,0,0}});},"Reject duplicate key times");rejects([]{PoseAnimation({{0,0,1,0},{1,2,0,0}});},"Reject non-normalized standing pose");rejects([]{PoseAnimation({{0,0,1,0},{1,1,1,0,PoseEvent::GetUpFinished}});},"Completion must mark the standing terminal pose");rejects([]{PoseAnimation({{0,0,1,0},{1,1,0,0,PoseEvent::GetUpFinished},{2,1,0,0}});},"Reject a premature completion marker");rejects([&]{clip.tick(-.01);},"Reject negative animation time");
}
void gameplay(){
    for(const bool switched:{false,true}){
        Player player(Terrain({floor()}));crash_landing(player,switched);const auto camera=player.camera_forward();const auto serial=player.placement_serial();bool getting_up=false;double last_progress=-1;
        for(unsigned i=0;i<420&&player.recovering();++i){const auto before=player.rider();player.tick({1,true,false,true,1});
            require(player.rider().launches==0&&player.rider().spin_degrees==0,"Recovery ignores charge/spin/boost control");
            if(player.recovering())near(dot(player.camera_forward(),camera),1,1e-9,"Tumble/get-up does not rotate the view frame");
            if(player.rider().control==Control::RecoverWait){getting_up=true;require(player.rider().recovery_standing>=last_progress,"Get-up track advances monotonically");last_progress=player.rider().recovery_standing;near(length(player.render_board_position()-player.render_position()),player.rider().recovery_height,1e-9,"Animation root height affects board presentation, not the camera anchor");if(before.control==Control::Wipeout){require(length(player.rider().position-before.position)<1,"Recovery placement is near the current crash position");require(length(player.rider().velocity)>1,"Relative get-up carries tangent momentum");const auto paused=player.rider();player.advance(0,{});near(player.rider().recovery_standing,paused.recovery_standing,0,"Pause freezes get-up progress");}}
        }
        require(getting_up&&!player.recovering()&&player.rider().recoveries==1&&player.rider().crashes==1,"Settled crash plays get-up and resumes once at its marker");require(player.rider().grounded&&player.rider().control==Control::Cruise,"Standing completion resumes grounded control");require(player.placement_serial()==serial&&player.rider().position.x>90,"Relative recovery does not warp to the course spawn");near(dot(player.rider().board_up,{0,1,0}),1,1e-5,"Completed pose is upright before ordinary bank control");require(player.rider().lead==(switched?-1:1),"Get-up keeps switch stance");
    }
    Player heavy(Terrain({floor()}));heavy.warp({0,.1,0},{0,0,-1},{0,-31,-5});heavy.tick({});require(heavy.rider().crash_cause==CrashCause::Landing&&heavy.rider().crashes==1,"Excessive downward impact triggers a hard landing");
    for(const auto surface:{6,10}){Player wall(Terrain({floor(surface)}));wall.warp({0,-.005,0},{0,0,-1},{0,0,-12});wall.tick({});require(wall.rider().crash_cause==CrashCause::Unrideable,"Bounce and wall rows trigger wipeout at contact speed");Player slow(Terrain({floor(surface)}));slow.warp({0,-.005,0},{0,0,-1},{0,0,-1});slow.tick({});require(slow.rider().crashes==0,"Unrideable trigger retains its speed gate");}
    Player rock(Terrain({floor(9)}));rock.warp({0,-.005,0},{0,0,-1},{0,0,-12});rock.tick({});require(rock.rider().crashes==0,"A hard rideable material is not an unrideable surface");
    for(const bool racing:{false,true}){auto spawn=floor();for(auto& p:spawn.points)p.x+=3000;Player reset(Terrain({floor(0),spawn}));reset.run_active(racing);reset.warp({100,-.005,0},{0,0,-1},{0,0,-1});const auto serial=reset.placement_serial();reset.tick({});for(unsigned j=0;j<60&&reset.reset_pending();++j)reset.tick({});require((reset.placement_serial()!=serial)==racing,"Reset surface is an ordinary physics row; automatic course reset belongs to an active run");}
    PlayTuning unresolved;unresolved.tumble_ground_drag=0;for(const bool racing:{false,true}){Player player(Terrain({floor()}),unresolved);player.run_active(racing);crash_landing(player);const auto serial=player.placement_serial();for(unsigned i=0;i<200&&player.rider().control==Control::Wipeout;++i)player.tick({});for(unsigned j=0;j<60&&player.reset_pending();++j)player.tick({});if(racing)require(player.placement_serial()>serial&&player.rider().crashes==0,"Unresolved contact timeout requests course reset during an active run");else require(player.placement_serial()==serial&&player.rider().control==Control::RecoverWait,"Finished/free riding uses relative get-up at the contact timeout");}
    for(const bool racing:{false,true}){auto ledge=floor();for(auto& p:ledge.points)p*=.01;Player player(Terrain({ledge}),unresolved);player.run_active(racing);player.warp({0,.1,-9},{0,0,-1},{0,-12,-12},{0,-1,0});player.tick({});require(player.rider().crashes==1,"Air-timeout fixture first crashes on the ledge");const auto serial=player.placement_serial();for(unsigned i=0;i<500&&player.rider().control==Control::Wipeout;++i)player.tick({});for(unsigned j=0;j<60&&player.reset_pending();++j)player.tick({});if(racing)require(player.placement_serial()>serial,"Unresolved seven-second fall resets an active run");else require(player.placement_serial()==serial&&player.rider().control==Control::RecoverWait&&player.rider().crash_age>7&&!player.rider().grounded,"Finished/free fall reaches relative recovery after seven seconds without an early bounds warp");}
}
void profiles(){
    const auto root=std::filesystem::temp_directory_path()/("openslope-recovery-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));std::filesystem::create_directory(root);struct Cleanup{std::filesystem::path path;~Cleanup(){std::error_code ec;std::filesystem::remove_all(path,ec);}}cleanup{root};
    const auto patch=floor();Json points=Json::array();for(const auto p:patch.points)points.push_back({p.x*100,-p.z*100,p.y*100});std::ofstream(root/"Patches.json")<<Json{{"Patches",Json::array({{{"PatchName","Authored recovery floor"},{"Points",points},{"SurfaceType",1},{"TrickOnlyPatch",false},{"UVPoints",{{0,0},{1,0},{0,1},{1,1}}},{"TexturePath",""},{"LightmapID",-1},{"LightMapPoint",{0,0,0,0}}}})}};
    auto profile=Json{{"Schema","openslope-rider-animation/v1"},{"GetUp",Json::array({{{"Time",0},{"Standing",0},{"Crouch",1},{"Height",.3}},{{"Time",.1},{"Standing",1},{"Crouch",0},{"Height",0}}})}};const auto write=[&]{std::ofstream(root/"RiderAnimations.json")<<profile;};write();Player held(Terrain::load(root));crash_landing(held);for(unsigned i=0;i<600;++i)held.tick({1,true,false,true,1});require(held.rider().control==Control::RecoverWait&&held.rider().recoveries==0,"A missing animation marker holds get-up beyond any crash-age timer");held.release_inputs();require(held.rider().control==Control::RecoverWait,"Focus loss does not forge completion");held.advance(1./60,{0,false,true});for(unsigned j=0;j<60&&held.reset_pending();++j)held.tick({});require(!held.recovering()&&held.rider().recovery_height==0,"Manual reset cancels an unfinished pose track");
    profile["GetUp"][1]["Event"]="get-up-finished";write();auto short_clip=PoseAnimation::get_up(root);short_clip.play();short_clip.tick(.1);require(short_clip.take(PoseEvent::GetUpFinished),"A custom clip's terminal marker controls its completion");profile["GetUp"][1]["Time"]=-1;write();rejects([&]{PoseAnimation::get_up(root);},"Reject malformed authored clip before play");profile["Schema"]="wrong";write();rejects([&]{PoseAnimation::get_up(root);},"Reject unknown animation profile schemas");
}
}
int main(){try{clips();gameplay();profiles();std::cout<<"PASS: "<<checks<<" animation-event, crash, relative recovery, pause and run-boundary checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
